solution_code:
#include <stddef.h>

void swap_int(int *a, int *b)
{
    if (a == NULL || b == NULL)
        return;             /* defensive: nothing to swap */

    int tmp = *a;           /* works even when a == b: tmp, *a, *b are all the same value */
    *a = *b;
    *b = tmp;
}

