solution_code:
void reverse_range(int *first, int *last)
{
    /* Invariant: [first, last) is the part that is still unreversed. */
    while (first < last) {
        --last;                 /* last now points at a real element */
        if (first == last)      /* odd length: the middle element stays put */
            break;
        int tmp = *first;
        *first = *last;
        *last = tmp;
        ++first;
    }
}

