solution_code:
#include <stddef.h>

void *my_memmove(void *dst, const void *src, size_t n)
{
    unsigned char *d = dst;
    const unsigned char *s = src;

    if (d == s || n == 0)
        return dst;

    if (d < s) {
        /* destination below source: forward copy never clobbers unread bytes */
        while (n--)
            *d++ = *s++;
    } else {
        /* destination above source: copy from the end backwards */
        d += n;
        s += n;
        while (n--)
            *--d = *--s;
    }
    return dst;
}

