#include <string.h>

/* Format a value in hundredths as "[-]I.FF", e.g. -1234 -> "-12.34". */
static const char *fmt_centi(int32_t v)
{
    char buf[16];
    char *p = buf + sizeof buf;
    uint32_t mag = v < 0 ? 0u - (uint32_t)v : (uint32_t)v;

    *--p = '\0';
    *--p = (char)('0' + mag % 10u); mag /= 10u;   /* hundredths */
